abrirCliente(clienteId: string): void {
  const cliente = this.clientes.find(c => c.id === clienteId);   // linha 1

  if (!clienteId) {                                             // linha 2
    this.mensagem = 'Cliente não encontrado';
    return;
  }

  this.titulo = cliente.nome;                                    // linha 3
}

